/* Icono Hamburguesa */
#iconoHamburguesa {
  display: inline-block;
  width: 60px;
  height: 60px;
  border-radius: 100px;
  -webkit-transition: 0.3s;
  -moz-transition: 0.3s;
  -o-transition: 0.3s;
  transition: 0.3s;
  cursor: pointer;
}
#iconoHamburguesa .rayitas {
  position: relative;
  top: 17px;
  left: 14px;
}
#iconoHamburguesa span {
  display: block;
  position: absolute;
  height: 4px;
  width: 55%;
  background: #fff; /* color de las rayitas */
  opacity: 1;
  left: 0;
  -webkit-transform: rotate(0deg);
  -moz-transform: rotate(0deg);
  -o-transform: rotate(0deg);
  transform: rotate(0deg);
  -webkit-transition: .25s ease-in-out;
  -moz-transition: .25s ease-in-out;
  -o-transition: .25s ease-in-out;
  transition: .25s ease-in-out;
}

#iconoHamburguesa span:nth-child(1) {
  top: 0px;
}
#iconoHamburguesa span:nth-child(2),#iconoHamburguesa span:nth-child(3) {
  top: 11px;
}
#iconoHamburguesa span:nth-child(4) {
  top: 22px;
}

#iconoHamburguesa.open span:nth-child(1) {
  top: 18px;
  width: 0%;
  left: 50%;
}
#iconoHamburguesa.open span:nth-child(2) {
  -webkit-transform: rotate(45deg);
  -moz-transform: rotate(45deg);
  -o-transform: rotate(45deg);
  transform: rotate(45deg);
}
#iconoHamburguesa.open span:nth-child(3) {
  -webkit-transform: rotate(-45deg);
  -moz-transform: rotate(-45deg);
  -o-transform: rotate(-45deg);
  transform: rotate(-45deg);
}
#iconoHamburguesa.open span:nth-child(4) {
  top: 18px;
  width: 0%;
  left: 50%;
}

@media only screen and (max-width: 768px) {
  #iconoHamburguesa {
    width: 45px;
    height: 45px;
  }
  #iconoHamburguesa .rayitas {
    top: 13px;
    left: 10px;
  }
  #iconoHamburguesa span {
    height: 3px;
  }

  #iconoHamburguesa span:nth-child(2),#iconoHamburguesa span:nth-child(3) {
    top: 8px;
  }
  #iconoHamburguesa span:nth-child(4) {
    top: 16px;
  }
  .seccion-menu.mostrar-seccion-menu {
  padding-top: 25px !important;
  } 
}

/* Monstrar sección menú */
.seccion-menu.mostrar-seccion-menu {
  transform: translateX(0%) translateY(0%);
  transition: visibility 0s,opacity .6s,transform .8s;
  opacity: 1;
  visibility: visible;	
 }

